package com.bdis.modules.experiment.service.impl;
import com.bdis.common.exception.*;
import com.bdis.common.utils.CurrentUserUtils;
import com.bdis.modules.experiment.constant.ExperimentArchiveStatus;
import com.bdis.modules.experiment.entity.*;
import com.bdis.modules.experiment.mapper.*;
import com.bdis.modules.experiment.request.ExperimentRecordVersionRequest;
import com.bdis.modules.experiment.service.ExperimentRecordVersionService;
import java.time.LocalDateTime; import java.util.List; import java.util.Objects;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ExperimentRecordVersionServiceImpl implements ExperimentRecordVersionService { private final ExperimentRecordMapper recordMapper; private final ExperimentRecordVersionMapper versionMapper; public ExperimentRecordVersionServiceImpl(ExperimentRecordMapper r,ExperimentRecordVersionMapper v){recordMapper=r;versionMapper=v;} @Override @Transactional public ExperimentRecordVersionEntity create(Long id,ExperimentRecordVersionRequest req){Long uid=CurrentUserUtils.currentUserId();if(uid==null)throw new ForbiddenException("Authentication is required");ExperimentRecordEntity record=recordMapper.selectById(id);if(record==null)throw new ResourceNotFoundException("Experiment record not found");if(!Objects.equals(uid,record.getRecorderId()))throw new ForbiddenException("Only record owner can create a version");if(!ExperimentArchiveStatus.RETURNED.equals(record.getArchiveStatus())&&!ExperimentArchiveStatus.DRAFT.equals(record.getArchiveStatus()))throw new BusinessException("Only draft or returned records can create a version");if(req==null||req.getExperimentTitle()==null||req.getExperimentTitle().isBlank())throw new BusinessException("Experiment title is required");List<ExperimentRecordVersionEntity> all=versionMapper.selectByRecordId(id);ExperimentRecordVersionEntity e=new ExperimentRecordVersionEntity();e.setRecordId(id);e.setVersionNo(all.size()+1);e.setReportFileId(req.getReportFileId());e.setExperimentTitle(req.getExperimentTitle());e.setExperimentProcess(req.getExperimentProcess());e.setExperimentResult(req.getExperimentResult());e.setSubmittedBy(uid);e.setSubmittedAt(LocalDateTime.now());e.setStatus("submitted");e.setCreatedAt(LocalDateTime.now());e.setUpdatedAt(LocalDateTime.now());versionMapper.insert(e);return e;} @Override @Transactional(readOnly=true) public List<ExperimentRecordVersionEntity> list(Long id){if(recordMapper.selectById(id)==null)throw new ResourceNotFoundException("Experiment record not found");return versionMapper.selectByRecordId(id);} }
